// Edit these two values for your business.
const APPOINTMENT_MINUTES = 30;
const TIME_ZONE = 'America/New_York';

// Vapi sends: { message: { type: 'tool-calls', toolCallList: [{ id, function: { name, arguments } }] } }
const call = $json.body?.message?.toolCallList?.[0] ?? {};
let args = call.function?.arguments ?? {};
if (typeof args === 'string') {
  try { args = JSON.parse(args); } catch (e) { args = {}; }
}

// start_time should be ISO 8601. If the assistant leaves out the offset, read it in TIME_ZONE.
const start = DateTime.fromISO(String(args.start_time ?? ''), { zone: TIME_ZONE });
const valid = Boolean(call.id) && start.isValid;
const end = valid ? start.plus({ minutes: APPOINTMENT_MINUTES }) : null;

return {
  json: {
    toolCallId: call.id ?? '',
    valid,
    name: String(args.name ?? '').trim() || 'Caller',
    phone: String(args.phone ?? '').trim(),
    email: String(args.email ?? '').trim(),
    reason: String(args.reason ?? '').trim() || 'Appointment',
    start: valid ? start.toISO() : '',
    end: valid ? end.toISO() : '',
    spokenTime: valid ? start.setZone(TIME_ZONE).toFormat("cccc, LLLL d 'at' h:mm a") : '',
  },
};

